      "<div class='modal-disclaimer'><strong>⚠️ 免责声明：</strong>该事件主要依据英国媒体报道与赛后视频回放，当值裁判与西甲官方未对此做出追加处罚认定。本档案仅记录公开讨论，不代表最终事实判定。</div>"
